/**
 * Enforces log retention in system context for all integration logs.
 * Small purges complete synchronously; larger backlogs use Batch Apex.
 */
public without sharing class LogPurgeJob
    implements Schedulable, Database.Batchable<SObject> {

    private Datetime normalCutoff;
    private Datetime errorCutoff;

    public LogPurgeJob() {
    }

    public static Id scheduleNightly() {
        // Salesforce interprets the schedule in the scheduling user's time zone.
        return System.schedule(
            'Log purge (nightly)',
            '0 0 2 * * ?',
            new LogPurgeJob()
        );
    }

    public void execute(SchedulableContext context) {
        initializeCutoffs();

        Integer availableDmlRows =
            Limits.getLimitDmlRows() - Limits.getDmlRows();
        Integer probeLimit = availableDmlRows + 1;

        List<FB_Integration_Log__c> expiredLogs = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :normalCutoff
              AND (
                  Level__c = null
                  OR Level__c != 'ERROR'
                  OR CreatedDate < :errorCutoff
              )
            LIMIT :probeLimit
        ];

        if (expiredLogs.isEmpty()) {
            return;
        }

        if (
            expiredLogs.size() <= availableDmlRows
            && Limits.getDmlStatements() < Limits.getLimitDmlStatements()
        ) {
            delete expiredLogs;
        } else {
            // The cutoffs are serialized with this instance, keeping the
            // retention boundary fixed for the entire run.
            Database.executeBatch(this, 200);
        }
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        // Also support direct execution through Database.executeBatch.
        if (normalCutoff == null || errorCutoff == null) {
            initializeCutoffs();
        }

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :normalCutoff
              AND (
                  Level__c = null
                  OR Level__c != 'ERROR'
                  OR CreatedDate < :errorCutoff
              )
        ]);
    }

    public void execute(
        Database.BatchableContext context,
        List<SObject> scope
    ) {
        // Let deletion failures surface in the batch job's error reporting.
        delete scope;
    }

    public void finish(Database.BatchableContext context) {
    }

    private void initializeCutoffs() {
        Datetime runTime = System.now();
        normalCutoff = runTime.addDays(-30);
        errorCutoff = runTime.addDays(-180);
    }
}
