        ((IOpportunitiesSelector) fixture.mocks.verify(
            fixture.selectorMock,
            1
        )).selectById((Set<Id>) anyValue());

        verifyApplicationCount(fixture, 1);
        verifyCommitCount(fixture, 1);

        // Also verify exact arguments and ordering across all three mocks.
        fflib_InOrder ordered = new fflib_InOrder(
            fixture.mocks,
            new List<Object>{
                fixture.selectorMock,
                fixture.domainMock,
                fixture.uowMock
            }
