public with sharing class AccountOnboardingService {
    public static List<Account> createAccountsWithContacts(
        Map<String, List<String>> contactLastNamesByAccountName
    ) {
        List<Account> accounts = new List<Account>();
        if (contactLastNamesByAccountName == null ||
            contactLastNamesByAccountName.isEmpty()) {
            return accounts;
        }

        // Insert parents before children and enforce the caller's CRUD/FLS.
        fflib_SObjectUnitOfWork unitOfWork = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType
            },
            new fflib_SObjectUnitOfWork.UserModeDML(AccessLevel.USER_MODE)
        );

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account newAccount = new Account(Name = accountName);
            accounts.add(newAccount);
            unitOfWork.registerNew(newAccount);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null) {
                continue;
            }

            for (String lastName : lastNames) {
                Contact newContact = new Contact(LastName = lastName);
                unitOfWork.registerNew(
                    newContact,
                    Contact.AccountId,
                    newAccount
                );
            }
        }

        unitOfWork.commitWork();
        return accounts;
    }
}
