public inherited sharing class Application {
    public static final fflib_Application.UnitOfWorkFactory UnitOfWork =
        new fflib_Application.UnitOfWorkFactory(
            new List<SObjectType>{
                Account.SObjectType,
                Opportunity.SObjectType,
                Deal_Won__e.SObjectType
            }
        );

    public static final fflib_Application.SelectorFactory Selector =
        new fflib_Application.SelectorFactory(
            new Map<SObjectType, Type>{
                Opportunity.SObjectType => OpportunitiesSelector.class
            }
        );

    /*
     * fflib's after-success hook runs after successful UoW DML, not after
     * the enclosing Salesforce transaction commits. Publish Immediately
     * events therefore require a transactional asynchronous handoff.
     *
     * This adapter uses user-mode record DML and defers publication.
     * Rolling back the originating transaction also rolls back its
     * queued job.
     */
    public class AfterCommitEventDML
        extends fflib_SObjectUnitOfWork.UserModeDML {

        public AfterCommitEventDML() {
            super(AccessLevel.USER_MODE);
        }

        public override void eventPublish(List<SObject> events) {
            if (events == null || events.isEmpty()) {
                return;
            }

            System.enqueueJob(new PublishEventsJob(events));
        }
    }

    private class PublishEventsJob implements Queueable {
        private List<SObject> events;

        private PublishEventsJob(List<SObject> events) {
            this.events = new List<SObject>();
            this.events.addAll(events);
        }

        public void execute(QueueableContext context) {
            /*
             * This job runs only after the originating transaction commits.
             * Delegate publication to fflib without creating or committing
             * another unit of work.
             */
            fflib_SObjectUnitOfWork.IDML publisher =
                new fflib_SObjectUnitOfWork.UserModeDML(
                    AccessLevel.USER_MODE
                );

            publisher.eventPublish(events);
        }
    }
}
