        'last',
        'lastday',
        'lastdayofmonth',
        'lastdayofthemonth'
    };

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> createdIds = new List<Id>();
        if (requests == null || requests.isEmpty()) {
            return createdIds;
        }

        // Validate the entire batch before performing any DML.
        Set<Id> contactIds = new Set<Id>();
        Boolean needsLastDay = false;

        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest request = requests[i];
            validateRequest(request, i + 1);
            contactIds.add(request.contactId);

            if (request.dayOfMonth == 31) {
                needsLastDay = true;
            }
        }

        // Describe does not consume a SOQL query. Resolve the actual API value,
        // rather than assuming that a display label is a valid picklist value.
        String lastDayValue =
            needsLastDay ? resolveLastDayValue() : null;

        Map<Id, Contact> donorsById = new Map<Id, Contact>([
            SELECT Id, Name
            FROM Contact
            WHERE Id IN :contactIds
            WITH USER_MODE
        ]);

        List<npe03__Recurring_Donation__c> donations =
            new List<npe03__Recurring_Donation__c>();

        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest request = requests[i];
            Contact donor = donorsById.get(request.contactId);

            if (donor == null) {
                throw new RecurringGiftException(
                    'Request ' + (i + 1) +
                    ': the donor contact does not exist or is not accessible.'
                );
            }

            Boolean isFixed =
                request.installments != null && request.installments > 0;
            String donationName = 'Monthly Gift - ' + donor.Name;

            donations.add(new npe03__Recurring_Donation__c(
                Name = donationName.left(80),
                npe03__Contact__c = request.contactId,
                npe03__Amount__c = request.amount,
                npe03__Date_Established__c = request.startDate,
                npe03__Installment_Period__c = 'Monthly',
                npe03__Installments__c =
                    isFixed ? request.installments : null,
                npsp__RecurringType__c = isFixed ? 'Fixed' : 'Open',
                npsp__InstallmentFrequency__c = 1,
                npsp__Day_of_Month__c =
                    request.dayOfMonth == 31
                        ? lastDayValue
                        : String.valueOf(request.dayOfMonth),
                npsp__StartDate__c = request.startDate,
                npsp__Status__c = 'Active',
                npsp__PaymentMethod__c = request.paymentMethod
            ));
        }

        /*
         * Use Enhanced RD's last-day picklist option, not the legacy checkbox.
         * Leave legacy schedule/status fields and derived end/next-payment
         * dates unset. NPSP owns scheduling and Opportunity generation.
         *
         * One all-or-none DML statement enforces the caller's permissions.
         */
        insert as user donations;

        for (npe03__Recurring_Donation__c donation : donations) {
            createdIds.add(donation.Id);
        }
        return createdIds;
    }

    private static String resolveLastDayValue() {
        List<Schema.PicklistEntry> options =
            npe03__Recurring_Donation__c.npsp__Day_of_Month__c
                .getDescribe()
                .getPicklistValues();

        // Prefer API-name matching, which is independent of label translation.
        for (Schema.PicklistEntry option : options) {
            if (
                option.isActive() &&
                LAST_DAY_KEYS.contains(normalizeOption(option.getValue()))
            ) {
                return option.getValue();
            }
        }

        // A label can identify the option, but only its API value is stored.
        for (Schema.PicklistEntry option : options) {
            if (
                option.isActive() &&
                LAST_DAY_KEYS.contains(normalizeOption(option.getLabel()))
            ) {
                return option.getValue();
            }
        }

        throw new RecurringGiftException(
            'The Enhanced Recurring Donations Day of Month field has no ' +
            'recognizable active last-day-of-month option.'
        );
    }

    private static String normalizeOption(String value) {
        return value == null
            ? ''
            : value.toLowerCase().replaceAll('[^a-z0-9]', '');
    }

    private static void validateRequest(
        GiftRequest request,
        Integer requestNumber
    ) {
        String prefix = 'Request ' + requestNumber + ': ';

        if (request == null) {
            throw new RecurringGiftException(
                prefix + 'the request must not be null.'
            );
        }
        if (request.contactId == null) {
            throw new RecurringGiftException(
                prefix + 'contactId is required.'
            );
        }
        if (request.amount == null || request.amount <= 0) {
            throw new RecurringGiftException(
                prefix + 'amount must be greater than zero.'
            );
        }
        if (
            request.dayOfMonth == null ||
            request.dayOfMonth < 1 ||
            request.dayOfMonth > 31
        ) {
            throw new RecurringGiftException(
                prefix + 'dayOfMonth must be between 1 and 31.'
            );
        }
        if (request.startDate == null) {
            throw new RecurringGiftException(
                prefix + 'startDate is required.'
            );
        }
        if (request.installments != null && request.installments < 0) {
            throw new RecurringGiftException(
                prefix + 'installments must be null, zero, or positive.'
            );
        }
        if (!PAYMENT_METHODS.contains(request.paymentMethod)) {
            throw new RecurringGiftException(
                prefix + 'paymentMethod must be Credit Card, ACH, or Check.'
            );
        }
    }
}
