public without sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validateContacts(triggerNew, new Map<Id, Contact>());
    }

    public void beforeUpdate(
        List<SObject> triggerNew,
        List<SObject> triggerOld
    ) {
        Map<Id, Contact> oldById = new Map<Id, Contact>();
        for (SObject oldRecord : triggerOld) {
            oldById.put(oldRecord.Id, (Contact) oldRecord);
        }
        validateContacts(triggerNew, oldById);
    }

    private static void validateContacts(
        List<SObject> triggerNew,
        Map<Id, Contact> oldById
    ) {
        List<PendingChange> pending = new List<PendingChange>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Set<Id> departingIds = new Set<Id>();

        for (SObject newRecord : triggerNew) {
            Contact current = (Contact) newRecord;
            Contact previous = oldById.get(current.Id);

            // Already-invalid records will not occupy their proposed new keys.
            // Their persisted values remain included in the query below.
            if (current.hasErrors()) {
                continue;
            }

            if (
                previous != null &&
                current.AccountId == previous.AccountId &&
                sameEmailValue(current.Email, previous.Email)
            ) {
                continue;
            }

            String newKey = keyFor(current);
            String oldKey = keyFor(previous);

            // Account for updates that vacate a key, including clearing either
            // field. Case-only changes do not vacate the normalized key.
            if (previous != null && oldKey != newKey) {
                departingIds.add(current.Id);
            }

            if (newKey == null) {
                continue;
            }

            pending.add(new PendingChange(current, newKey, oldKey));
            accountIds.add(current.AccountId);
            emails.add(current.Email.toLowerCase());
        }

        if (pending.isEmpty()) {
            return;
        }

        Map<String, Set<Id>> storedOwners = new Map<String, Set<Id>>();

        // Intentionally system-mode/without-sharing: this integrity rule must
        // include Contacts the user cannot see. No matching details are exposed.
        // SOQL comparisons on the standard Email field are case-insensitive.
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
                AND Email IN :emails
                AND Id NOT IN :departingIds
        ]) {
            addOwner(storedOwners, keyFor(existing), existing.Id);
        }

        // All state is invocation-local so partial-save retries are revalidated.
        // Existing occupants take precedence; list order breaks ties between
        // otherwise eligible incoming records.
        Boolean rejectedInPass;
        do {
            rejectedInPass = false;
            Set<String> claimedKeys = new Set<String>();

            for (PendingChange change : pending) {
                if (change.rejected) {
                    continue;
                }

                Set<Id> owners = storedOwners.get(change.newKey);
                Boolean storedConflict =
                    owners != null &&
                    (
                        owners.size() > 1 ||
                        !owners.contains(change.contactRecord.Id)
                    );

                if (
                    !storedConflict &&
                    !claimedKeys.contains(change.newKey)
                ) {
                    claimedKeys.add(change.newKey);
                    continue;
                }

                change.contactRecord.addError(ERROR_MESSAGE);
                change.rejected = true;
                rejectedInPass = true;

                // A rejected update retains its old values. Restore that
                // occupancy and recheck earlier winners without another query.
                if (change.oldKey != null) {
                    addOwner(
                        storedOwners,
                        change.oldKey,
                        change.contactRecord.Id
                    );
                }
            }
        } while (rejectedInPass);
    }

    private static Boolean sameEmailValue(String current, String previous) {
        // String.equals is case-sensitive, so case-only edits are checked too.
        return current == null
            ? previous == null
            : current.equals(previous);
    }

    private static String keyFor(Contact contactRecord) {
        if (
            contactRecord == null ||
            contactRecord.AccountId == null ||
            String.isBlank(contactRecord.Email)
        ) {
            return null;
        }

        return String.valueOf(contactRecord.AccountId) +
            '|' +
            contactRecord.Email.toLowerCase();
    }

    private static void addOwner(
        Map<String, Set<Id>> ownersByKey,
        String key,
        Id ownerId
    ) {
        if (!ownersByKey.containsKey(key)) {
            ownersByKey.put(key, new Set<Id>());
        }
        ownersByKey.get(key).add(ownerId);
    }

    private class PendingChange {
        private Contact contactRecord;
        private String newKey;
        private String oldKey;
        private Boolean rejected = false;

        public PendingChange(
            Contact contactRecord,
            String newKey,
            String oldKey
        ) {
            this.contactRecord = contactRecord;
            this.newKey = newKey;
            this.oldKey = oldKey;
        }
    }
}
